import { Component, EventEmitter, Input, Output } from '@angular/core';
import { FormsModule } from '@angular/forms'; // Import FormsModule
import { Meal } from '../../../../entities/meals/model/meals.model';
import { MealsCardComponent } from '../../../../shared/components/cards/meals-card/meals-card.component';

@Component({
  selector: 'app-menu',
  imports: [MealsCardComponent , FormsModule],
  templateUrl: './menu.component.html',
  styleUrl: './menu.component.css'
})
export class MenuComponent {
  @Input() meals! : Meal[]
  inputValue : string = ''
  @Output() searchVal : EventEmitter<string> = new EventEmitter<string>();
  @Output() selectedMeal : EventEmitter<Meal> = new EventEmitter<Meal>();
  onInputChange() {
    this.searchVal.emit(this.inputValue)
  }

  onSelectMeal(meal : Meal) : void {
    this.selectedMeal.emit(meal)
  }
}
<div class="mt-6">
  <header class="flex items-center justify-between">
    <h1 class="text-3xl font-medium">Choose <span class="text-primary">Dishes</span></h1>
    <div class="search_field">
        <input type="text" placeholder="Search meals..." [(ngModel)]="inputValue" (input)="onInputChange()" class="py-2 px-4 min-w-[290px] shadow-sm shadow-gray-100 outline-none rounded-lg ">
    </div>
  </header>
  <div class="flex my-16 items-center gap-5">
    @for (meal of meals; track meal.id) {
    <app-meals-card (selectedMeal)="onSelectMeal($event)"  [meal]="meal"></app-meals-card>
    }
  </div>
</div>
